def halves(grid, sep=5):
    """(left, right) subgrids on either side of the first column equal to sep."""
    c = next(j for j in range(len(grid[0])) if all(r[j] == sep for r in grid))
    return [r[:c] for r in grid], [r[c+1:] for r in grid]

def is_complement(a, b, bg=0, fill=2):
    """True if b is exactly `fill` wherever a is bg and bg wherever a is not bg (same size)."""
    return all((v == bg) == (u == fill) for ra, rb in zip(a, b) for v, u in zip(ra, rb))

def overlay(prio, base):
    """Overlay two same-size grids; prio's nonzero cells win over base's."""
    return [[p if p else b for p, b in zip(rp, rb)] for rp, rb in zip(prio, base)]
